"""Temporal, safety-gated navigation policy with bounded progress memory."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop immediately when confidence is low or forward closing risk is high."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Hold briefly after a recent loss, then scan persistently in one direction."""
    visible = bool(observation["target_visible"])
    reliable = (
        visible
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if reliable:
        memory["scan_direction"] = memory.get("scan_direction", "SCAN_LEFT")
        if int(observation["track_age"]) < 2 and not memory.get("verified_once", False):
            memory["verified_once"] = True
            memory["state"] = "VERIFY"
            return "SLOW_DOWN", 0.80
        return None

    lost_steps = int(observation["lost_steps"])
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        return "STOP", 0.92

    direction = memory.get("scan_direction", "SCAN_LEFT")
    memory["scan_direction"] = direction
    memory["state"] = "SEARCH"
    return direction, 0.75


def propose_moves(observation, memory):
    """Order moves by bearing alignment while admitting only visible corridors."""
    bearing = float(observation["target_bearing"])
    candidates = []

    if abs(bearing) <= 12.0 and observation["corridor_center"]:
        candidates.append("FORWARD")
    if bearing < -12.0 and observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    if observation["corridor_center"]:
        candidates.append("FORWARD")
    if observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if observation["corridor_right"]:
        candidates.append("VEER_RIGHT")

    blocked = memory.get("blocked_actions", [])
    return list(dict.fromkeys(a for a in candidates if a not in blocked))


def progress_contract(observation, memory, candidates):
    """Choose an aligned move, excluding recently failed actions and breaking stagnation."""
    if not candidates:
        return None

    previous = memory.get("last_action")
    failed = bool(
        observation.get("last_action_failed", False)
        or observation.get("collision_detected", False)
    )
    blocked = list(memory.get("blocked_actions", []))
    if failed and previous in MOTION_ACTIONS and previous not in blocked:
        blocked.append(previous)
        blocked = blocked[-2:]
    memory["blocked_actions"] = blocked

    usable = [a for a in candidates if a not in blocked] or candidates
    bearing = float(observation["target_bearing"])
    preferred = (
        "VEER_LEFT" if bearing < -12.0 else
        "VEER_RIGHT" if bearing > 12.0 else
        "FORWARD"
    )

    distance_class = observation.get("target_distance_class")
    if distance_class == memory.get("last_distance_class") and previous in usable:
        memory["stagnation"] = min(int(memory.get("stagnation", 0)) + 1, 3)
    else:
        memory["stagnation"] = 0
    memory["last_distance_class"] = distance_class

    if memory["stagnation"] >= 2:
        alternatives = [a for a in usable if a != previous]
        if alternatives:
            return alternatives[0]
    if preferred in usable:
        return preferred
    if previous in usable:
        return previous
    return usable[0]


def termination_contract(observation, memory):
    """Return a high-confidence stationary fallback when no motion is admissible."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination into three outputs."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        candidates = [
            "VEER_LEFT" if float(observation["target_bearing"]) < 0.0 else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["last_action"] = action
    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
